"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["60026"],{99894(e){e.exports=JSON.parse('{"id":"V4-101","slug":"fractional-shares","term":"Fractional Shares","also_known_as":[],"difficulty":"Beginner","definition":"Fractional shares are portions of a single share, allowing investors to buy part of a share rather than a whole one.","explanation":["Traditionally, investors had to buy whole shares. If a company\u2019s share price was very high, small investors might not be able to afford even one share. Fractional share investing, offered by many brokers and investing apps, lets investors buy shares by amount rather than by number.","For example, if a share costs 500, an investor with 50 can buy one tenth of a share. If the share rises 10%, their holding rises from 50 to 55.","Fractional shares make it easier to build diversified portfolios with small amounts, invest a fixed sum regularly and reinvest dividends fully.","There are some limitations. Fractional shares are often held through the broker\u2019s records rather than directly, may not be transferable to another broker and may not carry full voting rights. Fractional shares created through dividend reinvestment plans and stock splits have existed for a long time, but app-based investing has made them much more widely available."],"note":"","total":1725,"prev":{"slug":"fractional-reserve-banking","term":"Fractional-Reserve Banking"},"next":{"slug":"franchise-model","term":"Franchise Model"}}')}}]);